// ===== Workflow settings: edit these before activating =====
const CONFIG = {
  defaultTimezone: 'UTC', // IANA zone, e.g. 'America/New_York'. Used when the request does not send one.
  openaiModel: 'gpt-4o', // 'gpt-4o-mini' is cheaper. Must support response_format json_schema.
  defaultAppointmentMinutes: 30, // Used when a follow-up has a start time but no end time.
};

const item = $input.first();
// Webhook: form fields / JSON are under `body`. Google Drive: the item itself is the file metadata.
const body = item.json.body ?? item.json;
const binaries = item.binary ?? {};
const audioKey =
  Object.keys(binaries).find((k) => /^(audio|video)\//.test(binaries[k].mimeType ?? '')) ??
  Object.keys(binaries)[0];
const audioUrl = typeof body.audio_url === 'string' ? body.audio_url.trim() : '';

if (!audioKey && !audioUrl) {
  throw new Error(
    'No audio received. Send a multipart file field (curl -F "audio=@meeting.mp3") or a JSON body with "audio_url".',
  );
}

const timezone = body.timezone || CONFIG.defaultTimezone;
if (!DateTime.now().setZone(timezone).isValid) throw new Error(`Unknown timezone "${timezone}".`);

// Relative dates in the recording ("next Tuesday at 3") are resolved against this moment.
let reference = body.meeting_datetime
  ? DateTime.fromISO(String(body.meeting_datetime), { zone: timezone })
  : DateTime.now().setZone(timezone);
if (!reference.isValid) reference = DateTime.now().setZone(timezone);

const speakersExpected = Number.parseInt(body.speakers_expected, 10);
const transcriptOptions = { speaker_labels: true, punctuate: true, format_text: true };
if (speakersExpected > 0) transcriptOptions.speakers_expected = speakersExpected;
if (body.language_code) transcriptOptions.language_code = String(body.language_code);
else transcriptOptions.language_detection = true;

const fileName = (audioKey && binaries[audioKey].fileName) || body.name || '';

return [
  {
    json: {
      source: audioKey ? 'upload' : 'url',
      audio_url: audioUrl,
      file_name: fileName,
      meeting_title: body.meeting_title || fileName.replace(/\.[^.]+$/, '') || 'Meeting',
      recipient_email: typeof body.recipient_email === 'string' ? body.recipient_email.trim() : '',
      timezone,
      reference_datetime: reference.toISO(),
      transcript_options: transcriptOptions,
      openai_model: CONFIG.openaiModel,
      default_appointment_minutes: CONFIG.defaultAppointmentMinutes,
    },
    ...(audioKey ? { binary: { audio: binaries[audioKey] } } : {}),
  },
];

const t = $input.first().json;
const input = $('Normalize input').first().json;

const clock = (ms) => {
  const s = Math.floor(ms / 1000);
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
};
const lines =
  Array.isArray(t.utterances) && t.utterances.length
    ? t.utterances.map((u) => `[${clock(u.start)}] Speaker ${u.speaker}: ${u.text}`)
    : [t.text ?? ''];
let transcript = lines.join('\n').trim();
if (!transcript) throw new Error(`AssemblyAI transcript ${t.id} is empty; the recording may be silent.`);

// ~350k characters is roughly 90k tokens, which fits gpt-4o's 128k context with room for the answer.
const MAX_CHARS = 350000;
const truncated = transcript.length > MAX_CHARS;
if (truncated) transcript = transcript.slice(0, MAX_CHARS);

const str = (description) => ({ type: 'string', description });
const nullable = (description) => ({ type: ['string', 'null'], description });
const object = (properties) => ({
  type: 'object',
  additionalProperties: false,
  required: Object.keys(properties),
  properties,
});

const schema = object({
  meeting_title: str('Short descriptive title for the meeting.'),
  executive_summary: str('3-6 sentence summary written for a busy executive.'),
  key_takeaways: { type: 'array', items: { type: 'string' }, description: 'Decisions, insights, and important facts.' },
  action_items: {
    type: 'array',
    items: object({
      task: str('The concrete next step.'),
      owner: nullable('Person responsible, if stated.'),
      due: nullable('Deadline as said, or YYYY-MM-DD if it can be resolved.'),
    }),
  },
  contacts: {
    type: 'array',
    description: 'People named in the meeting with their details.',
    items: object({
      name: nullable('Full name as stated.'),
      email: nullable('Email address, only if clearly stated.'),
      phone: nullable('Phone number, only if clearly stated.'),
      company: nullable('Company or organisation.'),
      role: nullable('Job title or role.'),
    }),
  },
  primary_contact_email: nullable('Email of the external person (client, prospect, candidate) who should receive these notes.'),
  appointment: object({
    detected: { type: 'boolean', description: 'True only if a follow-up with a specific date AND time was agreed.' },
    title: nullable('What the follow-up is, e.g. "Pricing review call".'),
    start_local: nullable('Local wall-clock start as YYYY-MM-DDTHH:mm, no offset.'),
    end_local: nullable('Local wall-clock end as YYYY-MM-DDTHH:mm, no offset. Null if not stated.'),
    timezone: nullable('IANA timezone (e.g. America/Chicago) only if a timezone or city was stated.'),
    location: nullable('Meeting place, phone, or video link if stated.'),
    evidence: nullable('Short verbatim quote from the transcript where the follow-up was agreed.'),
  }),
});

const reference = DateTime.fromISO(input.reference_datetime, { setZone: true });
const system = [
  'You are a meeting analyst. You receive a speaker-labelled transcript and return meeting notes as JSON matching the provided schema.',
  'Rules:',
  '- Use only information stated in the transcript. Never invent names, emails, phone numbers, companies, dates, or times; use null when something is not stated.',
  '- Speaker labels (Speaker A, Speaker B) are not names. Use a person\'s name only when it is said in the conversation.',
  '- Emails are often spoken ("jane dot doe at acme dot com"). Convert them to normal form (jane.doe@acme.com) only when every part is clear.',
  '- action_items are concrete commitments or next steps. A deadline is an action item, not an appointment.',
  '- appointment.detected is true only when participants agree on a specific follow-up meeting, call, demo, or appointment with both a date and a time. A vague plan ("let\'s talk next week") is an action item, not an appointment.',
  '- Resolve relative dates ("next Tuesday at 3pm") against the meeting reference date below. Return start_local and end_local as local wall-clock time YYYY-MM-DDTHH:mm without a UTC offset.',
  '- Write the notes in the language of the transcript.',
].join('\n');
const header = [
  `Meeting reference date/time: ${reference.toFormat('cccc, yyyy-LL-dd HH:mm')} (${input.timezone})`,
  `Title provided by the sender: ${input.meeting_title}`,
];
if (truncated) header.push('Note: the transcript was truncated because it is very long; summarise what is provided.');
const user = `${header.join('\n')}\n\nTranscript:\n"""\n${transcript}\n"""`;

return [
  {
    json: {
      transcript_id: t.id,
      audio_duration_seconds: t.audio_duration ?? null,
      transcript_truncated: truncated,
      transcript_text: transcript,
      openai_request: {
        model: input.openai_model,
        temperature: 0.2,
        response_format: {
          type: 'json_schema',
          json_schema: { name: 'meeting_notes', strict: true, schema },
        },
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
      },
    },
  },
];

const response = $input.first().json;
const choice = response.choices?.[0] ?? {};
if (choice.message?.refusal) throw new Error(`OpenAI refused the request: ${choice.message.refusal}`);
if (choice.finish_reason === 'length') throw new Error('OpenAI response was cut off before the JSON was complete.');

let notes;
try {
  notes = JSON.parse(choice.message?.content ?? '');
} catch (error) {
  throw new Error(`OpenAI did not return valid JSON: ${error.message}`);
}

const input = $('Normalize input').first().json;
const prep = $('Build OpenAI request').first().json;

const isEmail = (v) => typeof v === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim());
const contacts = (notes.contacts ?? []).map((c) => ({
  ...c,
  email: isEmail(c.email) ? c.email.trim().toLowerCase() : null,
}));
// The sender's explicit recipient wins; otherwise use the email the model found in the recording.
const recipient =
  [input.recipient_email, notes.primary_contact_email, ...contacts.map((c) => c.email)]
    .find(isEmail)
    ?.trim()
    .toLowerCase() ?? '';
const contact = contacts.find((c) => c.email === recipient) ?? {
  name: null, email: recipient || null, phone: null, company: null, role: null,
};

// Appointment: the model returns local wall-clock time; Luxon applies the timezone and DST.
const appt = notes.appointment ?? {};
const zone = appt.timezone && DateTime.now().setZone(appt.timezone).isValid ? appt.timezone : input.timezone;
let start = appt.detected && appt.start_local ? DateTime.fromISO(appt.start_local, { zone }) : null;
if (start && !start.isValid) start = null;
let end = start && appt.end_local ? DateTime.fromISO(appt.end_local, { zone }) : null;
if (start && (!end || !end.isValid || end <= start)) end = start.plus({ minutes: input.default_appointment_minutes });
const hasAppointment = Boolean(start);
const title = notes.meeting_title || input.meeting_title;
const followUpTitle = appt.title || `Follow-up: ${title}`;
const when = start ? `${start.toFormat("cccc, LLLL d, yyyy 'at' h:mm a")} (${zone})` : '';

// ---- Email body (HTML), shared by both paths
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);
const list = (items) => (items.length ? `<ul>${items.map((i) => `<li>${i}</li>`).join('')}</ul>` : '<p>None noted.</p>');
const greeting = contact.name ? `Hi ${esc(contact.name.split(' ')[0])},` : 'Hello,';
const emailHtml = [
  `<p>${greeting}</p>`,
  `<p>Here are the notes from <strong>${esc(title)}</strong>.</p>`,
  '<h3>Executive summary</h3>',
  `<p>${esc(notes.executive_summary)}</p>`,
  '<h3>Key takeaways</h3>',
  list((notes.key_takeaways ?? []).map(esc)),
  '<h3>Action items</h3>',
  list((notes.action_items ?? []).map((a) =>
    `${esc(a.task)}${a.owner ? ` <em>(owner: ${esc(a.owner)})</em>` : ''}${a.due ? ` <em>(due: ${esc(a.due)})</em>` : ''}`)),
  hasAppointment
    ? `<h3>Next meeting</h3><p><strong>${esc(followUpTitle)}</strong><br>${esc(when)}${appt.location ? `<br>${esc(appt.location)}` : ''}</p>`
    : '',
  '<p style="color:#666;font-size:12px">These notes were generated automatically from a recording. Reply if anything needs correcting.</p>',
].join('\n');

// ---- HubSpot payloads (null fields are left out so existing CRM values are not blanked)
const [firstname, ...rest] = (contact.name ?? '').trim().split(/\s+/);
const compact = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== null && v !== undefined && v !== ''));
const hubspotContact = compact({
  email: recipient,
  firstname: firstname || null,
  lastname: rest.join(' ') || null,
  company: contact.company,
  phone: contact.phone,
  jobtitle: contact.role,
});
const hubspotMeeting = hasAppointment
  ? compact({
      hs_timestamp: start.toUTC().toISO(),
      hs_meeting_title: followUpTitle,
      hs_meeting_start_time: start.toUTC().toISO(),
      hs_meeting_end_time: end.toUTC().toISO(),
      hs_meeting_outcome: 'SCHEDULED',
      hs_meeting_location: appt.location,
      hs_meeting_body: emailHtml,
    })
  : null;

const calendarDescription = [
  notes.executive_summary,
  '',
  'Action items:',
  ...(notes.action_items ?? []).map((a) => `- ${a.task}${a.owner ? ` (${a.owner})` : ''}`),
  '',
  `Contact: ${[contact.name, recipient, contact.phone].filter(Boolean).join(' | ')}`,
  appt.evidence ? `Agreed in the recording: "${appt.evidence}"` : '',
  `AssemblyAI transcript: ${prep.transcript_id}`,
].join('\n');

return [
  {
    json: {
      meeting_title: title,
      executive_summary: notes.executive_summary,
      key_takeaways: notes.key_takeaways,
      action_items: notes.action_items,
      contacts,
      recipient_email: recipient,
      contact,
      has_appointment: hasAppointment,
      appointment: hasAppointment
        ? {
            title: followUpTitle,
            start_iso: start.toISO(),
            end_iso: end.toISO(),
            timezone: zone,
            location: appt.location ?? '',
            evidence: appt.evidence ?? '',
            display: when,
          }
        : null,
      email_subject: hasAppointment ? `Meeting notes + next meeting: ${title}` : `Meeting notes: ${title}`,
      email_html: emailHtml,
      calendar_description: calendarDescription,
      hubspot_contact_properties: hubspotContact,
      hubspot_meeting_properties: hubspotMeeting,
      transcript_id: prep.transcript_id,
      audio_duration_seconds: prep.audio_duration_seconds,
      transcript_truncated: prep.transcript_truncated,
    },
  },
];
